//! Wire schema and bindings shared by the client, guest, and service adapters.

use base64::{
    engine::general_purpose::{STANDARD, URL_SAFE_NO_PAD},
    Engine,
};
use serde::{Deserialize, Serialize};
use serde_json::Value;
use sha2::{Digest, Sha384};

use crate::{valid_hex, validate_issuer, Error, Result};

pub const EVIDENCE_PATH: &str = "/attestation/evidence";
pub const INFERENCE_PATH: &str = "/v1/chat/completions";
pub const VERIFY_PATH: &str = "/v1/verify";
pub const POLICY_IDS: [&str; 2] = ["default", "application"];
pub const RUNTIME_PROFILE: &str = "coco.inference-background-check.v1";

/// Parse the exact HTTPS origin used to scope release approval and connect.
pub fn parse_audience(audience: &str) -> Result<url::Url> {
    validate_issuer(audience)?;
    let target = url::Url::parse(audience).map_err(|_| Error::Invalid("invalid audience URL"))?;
    if target.path() != "/" {
        return Err(Error::Invalid("inference audience must be an HTTPS origin"));
    }
    Ok(target)
}

/// CPU evidence for this profile always includes replayable boot and runtime
/// events. DCAP and the TDX verifier validate the decoded data separately.
pub fn require_tdx_evidence(evidence: &Value) -> Result<()> {
    for field in ["quote", "cc_eventlog"] {
        if !evidence[field].as_str().is_some_and(|encoded| {
            STANDARD
                .decode(encoded)
                .is_ok_and(|bytes| !bytes.is_empty())
        }) {
            return Err(Error::Invalid("TDX quote and CCEL are required"));
        }
    }
    Ok(())
}

/// Identifiers must come from the approved release and the actual inference
/// TLS connection. Challenge bytes are generated by InferenceSession.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct InferenceBinding {
    pub profile: String,
    pub audience: String,
    pub nonce: String,
    pub session_id: String,
    pub release_id: String,
    pub tls_spki_sha256: String,
}

impl InferenceBinding {
    pub fn validate(&self) -> Result<()> {
        parse_audience(&self.audience)?;
        if self.profile != RUNTIME_PROFILE
            || !valid_hex(&self.nonce, 32)
            || !valid_hex(&self.session_id, 32)
            || self.nonce == self.session_id
            || !valid_hex(&self.tls_spki_sha256, 32)
            || self.release_id.is_empty()
            || self.release_id.len() > 256
        {
            return Err(Error::Invalid("invalid inference runtime binding"));
        }
        Ok(())
    }

    pub fn report_data(&self) -> Result<Vec<u8>> {
        self.validate()?;
        Ok(Sha384::digest(serde_json_canonicalizer::to_vec(self)?).to_vec())
    }
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct InferenceChallenge {
    pub nonce: String,
    pub session_id: String,
}

/// Wire fields are private so callers use the same encoder or decoder.
#[derive(Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct InferenceRequest {
    #[serde(default)]
    known_signer_kids: Vec<String>,
    attestation_request: AttestationRequest,
}

#[derive(Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
struct AttestationRequest {
    verification_requests: Vec<TdxRequest>,
    policy_ids: Vec<String>,
}

#[derive(Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
struct TdxRequest {
    tee: String,
    evidence: String,
    runtime_data: StructuredRuntime,
    init_data: StructuredInitData,
    runtime_data_hash_algorithm: Option<String>,
}

#[derive(Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
struct StructuredRuntime {
    structured: InferenceBinding,
}

#[derive(Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
struct StructuredInitData {
    init_data_toml: String,
}

pub struct DecodedInferenceRequest {
    pub binding: InferenceBinding,
    pub evidence: Value,
    pub init_data_toml: String,
    pub include_signer: bool,
}

impl InferenceRequest {
    pub(super) fn new(
        known_signer_kids: Vec<String>,
        evidence: &Value,
        binding: &InferenceBinding,
        init_data_toml: &str,
    ) -> Result<Self> {
        require_tdx_evidence(evidence)?;
        Ok(Self {
            known_signer_kids,
            attestation_request: AttestationRequest {
                verification_requests: vec![TdxRequest {
                    tee: "tdx".into(),
                    evidence: URL_SAFE_NO_PAD.encode(serde_json::to_vec(evidence)?),
                    runtime_data: StructuredRuntime {
                        structured: binding.clone(),
                    },
                    init_data: StructuredInitData {
                        init_data_toml: init_data_toml.into(),
                    },
                    runtime_data_hash_algorithm: Some("sha384".into()),
                }],
                policy_ids: POLICY_IDS.map(String::from).into(),
            },
        })
    }

    pub fn decode(self, signer_kid: &str) -> Result<DecodedInferenceRequest> {
        if self.known_signer_kids.len() > 16
            || self.known_signer_kids.iter().any(|id| !valid_hex(id, 32))
        {
            return Err(Error::Invalid("invalid signer key hints"));
        }
        let include_signer = !self.known_signer_kids.iter().any(|kid| kid == signer_kid);
        let AttestationRequest {
            verification_requests,
            policy_ids,
        } = self.attestation_request;
        let [request]: [_; 1] = verification_requests
            .try_into()
            .map_err(|_| Error::Invalid("inference requires one report"))?;
        if policy_ids != POLICY_IDS {
            return Err(Error::Invalid("inference requires both policies"));
        }
        if request.tee != "tdx"
            || request
                .runtime_data_hash_algorithm
                .as_deref()
                .is_some_and(|alg| alg != "sha384")
        {
            return Err(Error::Invalid("inference requires native TDX and SHA-384"));
        }
        let evidence_bytes = URL_SAFE_NO_PAD
            .decode(request.evidence)
            .map_err(|_| Error::Invalid("invalid encoded TDX evidence"))?;
        let evidence: Value = serde_json::from_slice(&evidence_bytes)?;
        require_tdx_evidence(&evidence)?;
        if evidence.as_object().is_none_or(|object| object.len() != 2) {
            return Err(Error::Invalid("unexpected TDX evidence fields"));
        }
        let binding = request.runtime_data.structured;
        binding.validate()?;
        Ok(DecodedInferenceRequest {
            binding,
            evidence,
            init_data_toml: request.init_data.init_data_toml,
            include_signer,
        })
    }
}
